"""JVM tests: pure diff plus store transactions using a Gson-backed org.json test adapter. No network/APK."""
import pathlib,subprocess,tempfile,os
root=pathlib.Path(__file__).resolve().parents[2]
gson=next((pathlib.Path.home()/'.gradle/caches/modules-2/files-2.1/com.google.code.gson/gson/2.11.0').glob('*/*.jar'))
adapters={
'org/json/JSONObject.java':'''package org.json;import com.google.gson.*;public class JSONObject {final JsonObject obj;public JSONObject(){obj=new JsonObject();}public JSONObject(String s){obj=JsonParser.parseString(s).getAsJsonObject();}JSONObject(JsonObject o){obj=o;}public JSONObject put(String k,Object v){obj.add(k,new Gson().toJsonTree(v));return this;}public Object opt(String k){return wrap(obj.get(k));}static Object wrap(JsonElement e){if(e==null||e.isJsonNull())return null;if(e.isJsonObject())return new JSONObject(e.getAsJsonObject());if(e.isJsonArray())return new JSONArray(e.getAsJsonArray());return e.getAsString();}public String optString(String k,String d){Object o=opt(k);return o instanceof String?(String)o:d;}public long optLong(String k,long d){try{return obj.get(k).getAsLong();}catch(Exception e){return d;}}public int optInt(String k){return(int)optLong(k,0);}public boolean optBoolean(String k){try{return obj.get(k).getAsBoolean();}catch(Exception e){return false;}}public String toString(){return obj.toString();}}''',
'org/json/JSONArray.java':'''package org.json;import com.google.gson.*;public class JSONArray {final JsonArray array;JSONArray(JsonArray a){array=a;}public int length(){return array.size();}public Object opt(int i){return JSONObject.wrap(array.get(i));}}''',
'ArticleChangesStoreTest.java':r'''import org.telegram.ui.web.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;public class ArticleChangesStoreTest {static void check(boolean b){if(!b)throw new AssertionError();}static byte[] doc(String text){return ("{\"title\":\"Title\",\"content\":[{\"tag\":\"p\",\"content\":[\""+text+"\"]}]}").getBytes(StandardCharsets.UTF_8);}public static void main(String[]args)throws Exception{Path base=Paths.get(args[0]),old=Files.createDirectory(base.resolve("old")),next=Files.createDirectory(base.resolve("next"));ArticleChangesStore.prepare(old.toFile(),next.toFile(),doc("One"),1000);ArticleChangesStore.Comparison first=ArticleChangesStore.read(next.toFile());check(first!=null&&!first.hasPrevious);Files.write(next.resolve("document.json"),doc("One"));Path newer=Files.createDirectory(base.resolve("newer"));ArticleChangesStore.prepare(next.toFile(),newer.toFile(),doc("Two"),2000);ArticleChangesStore.Comparison result=ArticleChangesStore.read(newer.toFile());check(result.hasPrevious&&result.previousAt==1000&&result.currentAt==2000);check(result.lines.stream().anyMatch(x->x.kind==-1&&x.text.equals("One")));check(result.lines.stream().anyMatch(x->x.kind==1&&x.text.equals("Two")));check(ArticleChangesStore.read(next.toFile()).currentAt==1000);Path large=Files.createDirectory(base.resolve("large"));ArticleChangesStore.prepare(newer.toFile(),large.toFile(),doc("x".repeat(9000)),3000);check(ArticleChangesStore.read(large.toFile()).truncated);check(Files.size(large.resolve("changes.json"))<=ArticleChangesStore.MAX_BYTES);Files.write(large.resolve("changes.json"),new byte[ArticleChangesStore.MAX_BYTES+1]);check(ArticleChangesStore.read(large.toFile())==null);System.out.println("Article snapshots: first/save/update timestamps, added/removed text, previous unchanged, truncation and corrupt-size rejection passed");}}'''
}
# Java source needs ordinary JSON quoting, not literal backslashes before structural quotes.
adapters['ArticleChangesStoreTest.java']=adapters['ArticleChangesStoreTest.java'].replace('\\\\\\"','\\"')
with tempfile.TemporaryDirectory(prefix='article-change-tests-') as temp:
 paths=[]
 for name,source in adapters.items():
  p=pathlib.Path(temp,name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(source,encoding='utf8');paths.append(str(p))
 for name in ['ArticleTextDiff.java','ArticleChangesStore.java']:paths.append(str(root/'TMessagesProj/src/main/java/org/telegram/ui/web'/name))
 paths.append(str(root/'Tools/tests/ArticleTextDiffTest.java'))
 subprocess.run(['javac','-encoding','UTF-8','-cp',str(gson),'-d',temp,*paths],check=True)
 cp=temp+os.pathsep+str(gson)
 subprocess.run(['java','-cp',cp,'ArticleTextDiffTest'],check=True)
 subprocess.run(['java','-cp',cp,'ArticleChangesStoreTest',temp],check=True)
